export const useSendMessage = () => {
    const api = useApi();
    const getMessageKeys = useGetMessageKeys();
    const getAttachment = useGetAttachment();
    const dispatch = useDispatch();
    const { call } = useEventManager();
    const getMessage = useGetMessage();
    const history = useHistory<any>();
    const delaySendSeconds = useDelaySendSeconds();
    const { createNotification, hideNotification } = useNotifications();
    const sendModification = useSendModifications();

    const onUpdateAttachment = (ID: string, attachment: DecryptResultPmcrypto) => {
        dispatch(updateAttachment({ ID, attachment }));
    };

    return useCallback(
        async ({
            inputMessage,
            mapSendPrefs,
            onCompose,
            sendingMessageNotificationManager,
            useSilentApi = false,
        }: UseSendMessageParameters) => {
            const { localID, data } = inputMessage;
            const hasUndo = !!delaySendSeconds;

            const handleUndo = async () => {
                if (sendingMessageNotificationManager) {
                    hideNotification(sendingMessageNotificationManager.ID);
                }
                const savedMessage = getMessage(localID) as MessageStateWithData;
                const isScheduledMessage = savedMessage.draftFlags?.scheduledAt;
                const request = async () => {
                    if (isScheduledMessage) {
                        await dispatch(cancelScheduled(savedMessage.localID));
                        await api(cancelSend(savedMessage.data.ID));
                    } else {
                        await api(cancelSend(savedMessage.data.ID));
                    }
                    await call();
                };
                const promise = request();
                const undoingSendNotification = createNotification({
                    text: (
                        <LoadingNotificationContent
                            loadingText={c('Message notification').t`Undoing send...`}
                            loadedText={
                                isScheduledMessage
                                    ? c('Message notification').t`Scheduled sending undone`
                                    : c('Message notification').t`Sending undone`
                            }
                            promise={promise}
                        />
                    ),
                    expiration: -1,
                });
                const startTime = performance.now();
                try {
                    await promise;
                    const endTime = performance.now();
                    // Display the notification at least 1,5 second to let the user read it
                    setTimeout(
                        () => {
                            hideNotification(undoingSendNotification);
                        },
                        endTime - startTime > 2000 ? 0 : 1500
                    );
                } catch (error: any) {
                    hideNotification(undoingSendNotification);
                    throw error;
                }
                // Re-open draft
                onCompose({
                    existingDraft: {
                        localID,

            }

            createNotification({
                text: error.data.Error,
                type: 'error',
            });
            throw error;
        }
    }, []);
};

interface UseUpdateDraftParameters {
    onMessageAlreadySent?: () => void;
}

export const useSaveDraft = ({ onMessageAlreadySent }: UseUpdateDraftParameters = {}) => {
    const getMessage = useGetMessage();
    const updateDraft = useUpdateDraft();
    const createDraft = useCreateDraft();

    return useCallback(async (message: MessageStateWithData) => {
        const messageFromCache = getMessage(message.localID) as MessageState;

        if (messageFromCache?.data?.ID) {
            await updateDraft(message, onMessageAlreadySent);
        } else {
            await createDraft(message);
        }
    }, []);
};

export const useDeleteDraft = () => {
    const api = useApi();
    const [mailSettings] = useMailSettings();
    const [folders = []] = useFolders();
    const dispatch = useDispatch();
    const { call } = useEventManager();
    const { createNotification } = useNotifications();
    const getConversation = useGetConversation();

    return useCallback(
        async (message: MessageState) => {
            const showMoved = hasBit(mailSettings?.ShowMoved || 0, SHOW_MOVED.DRAFTS);
            const currentLabelID = showMoved ? ALL_DRAFTS : getCurrentFolderID(message.data?.LabelIDs, folders);
            const response: any = await api(deleteMessages([message.data?.ID], currentLabelID));

            // For the "Please refresh your page, the message has moved."
            // Backend is not replying with an HTTP error but with an error inside the Response
            // (it's to deal about potentially different statuses in several deletions)
            if (response?.Responses?.[0]?.Response?.Error) {
                const { Response } = response.Responses[0];
                createNotification({ text: Response.Error, type: 'error' });
                const error = new Error(Response.Error);
                (error as any).code = Response.Code;
                throw error;
            }

            dispatch(deleteDraft(message.localID));

            const conversationID = message.data?.ConversationID || '';
            const conversationFromConversationState = getConversation(conversationID);
            if (conversationFromConversationState && conversationFromConversationState.Messages?.length === 1) {
                dispatch(deleteConversation(conversationID));
            }

            await call();
        },
        [api, mailSettings]
    );
};
